    std::shared_ptr<Node> current = root;
    for (int i = 0; i < len; ++i) {
        unsigned char bit;
        infile.read(reinterpret_cast<char*>(&bit), sizeof(bit));
        if (bit == 0) {
            if (!current->left) {
                current->left = std::make_shared<Node>('\0', 0);
            }
            current = current->left;
        } else {
            if (!current->right) {
                current->right = std::make_shared<Node>('\0', 0);
            }
            current = current->right;
        }
    }
    current->ch = ch;
    current->freq = 1;
}

